//! Compare actual ordinary TLS ClientHellos with dae's pinned uTLS presets,
//! and relay VLESS over WebSocket through an independently running sing-box.
//!
//! The reference ClientHellos are generated by `go run .` under
//! `tests/fixtures/dae-utls-1.8.2`. To run the ignored end-to-end tests, set
//! `PATHCHORD_TEST_SING_BOX` to the sing-box 1.14.4 executable.

use std::{
    collections::BTreeMap,
    net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr},
    path::PathBuf,
    pin::Pin,
    process::Stdio,
    sync::Arc,
    task::{Context, Poll},
    time::Duration,
};

use pathchord_policy::{
    Endpoint as PolicyEndpoint, TransitOptions, TransitProxyConfig, TransitProxyId, TransitTls,
    TransitTransport,
};
use pathchord_transit::{
    AdapterRegistry, ConnectRequest, Endpoint, NoTransitCredentials, TransitAdapter,
    TransitCredential,
};
use rustls::pki_types::{PrivateKeyDer, PrivatePkcs8KeyDer, ServerName};
use serde_json::json;
use tokio::{
    io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt, ReadBuf},
    net::{TcpListener, TcpStream, UdpSocket},
    process::{Child, Command},
    sync::mpsc,
    task::JoinHandle,
    time::{Instant, sleep, timeout},
};
use tokio_rustls::{TlsAcceptor, TlsConnector};

const UUID: &str = "6cbf3f72-3417-4922-bde6-67820d041f25";
const SERVER_NAME: &str = "tls.pathchord.test";
const PATH: &str = "/socket/path";
const REQUEST_PATH: &str = "/socket/path";
const HOST: &str = "front.pathchord.test";
const HEADER: &str = "x-pathchord-fixture";
const HEADER_VALUE: &str = "custom-header";

#[derive(Clone, Copy, Debug)]
enum Profile {
    Chrome,
    Ios,
    Edge,
    Qq,
    Firefox,
}

impl Profile {
    fn name(self) -> &'static str {
        match self {
            Self::Chrome => "chrome",
            Self::Ios => "ios",
            Self::Edge => "edge",
            Self::Qq => "qq",
            Self::Firefox => "firefox",
        }
    }

    fn reference(self) -> &'static [u8] {
        match self {
            Self::Chrome => include_bytes!("fixtures/dae-utls-1.8.2/chrome.bin"),
            Self::Ios => include_bytes!("fixtures/dae-utls-1.8.2/ios.bin"),
            Self::Edge => include_bytes!("fixtures/dae-utls-1.8.2/edge.bin"),
            Self::Qq => include_bytes!("fixtures/dae-utls-1.8.2/qq.bin"),
            Self::Firefox => include_bytes!("fixtures/dae-utls-1.8.2/firefox.bin"),
        }
    }
}

struct Directory(PathBuf);

impl Directory {
    fn new() -> Self {
        let mut random = [0; 8];
        getrandom::fill(&mut random).unwrap();
        let path = std::env::temp_dir().join(format!(
            "pathchord-tls-fingerprint-{}-{:016x}",
            std::process::id(),
            u64::from_ne_bytes(random)
        ));
        #[cfg_attr(not(unix), allow(unused_mut))]
        let mut directory = std::fs::DirBuilder::new();
        #[cfg(unix)]
        {
            use std::os::unix::fs::DirBuilderExt;
            directory.mode(0o700);
        }
        directory.create(&path).unwrap();
        Self(path)
    }
}

impl Drop for Directory {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

struct Peer {
    child: Child,
    directory: Directory,
    address: SocketAddr,
    certificate: String,
    acceptor: TlsAcceptor,
    connector: TlsConnector,
}

impl Peer {
    async fn start(ip: IpAddr, tls12: bool) -> Self {
        let binary = PathBuf::from(
            std::env::var_os("PATHCHORD_TEST_SING_BOX")
                .expect("PATHCHORD_TEST_SING_BOX is required"),
        );
        let directory = Directory::new();
        let reserved = std::net::TcpListener::bind(SocketAddr::new(ip, 0)).unwrap();
        let address = reserved.local_addr().unwrap();
        let rcgen::CertifiedKey { cert, signing_key } =
            rcgen::generate_simple_self_signed(vec![SERVER_NAME.to_owned()]).unwrap();
        let certificate = cert.pem();
        let certificate_path = directory.0.join("server.pem");
        let key_path = directory.0.join("server.key");
        std::fs::write(&certificate_path, &certificate).unwrap();
        std::fs::write(&key_path, signing_key.serialize_pem()).unwrap();
        let mut tls = json!({
            "enabled": true, "certificate_path": certificate_path, "key_path": key_path,
            "alpn": ["http/1.1"]
        });
        if tls12 {
            tls["min_version"] = json!("1.2");
            tls["max_version"] = json!("1.2");
        }
        let config = json!({
            "log": {"level": "error"},
            "inbounds": [{
                "type": "vless", "listen": ip.to_string(), "listen_port": address.port(),
                "users": [{"uuid": UUID}], "tls": tls,
                "transport": {"type": "ws", "path": PATH}
            }],
            "outbounds": [{"type": "direct"}]
        });
        let config_path = directory.0.join("server.json");
        std::fs::write(&config_path, serde_json::to_vec(&config).unwrap()).unwrap();
        let log = std::fs::File::create(directory.0.join("server.log")).unwrap();
        drop(reserved);
        let child = Command::new(binary)
            .args(["run", "-c"])
            .arg(config_path)
            .stdin(Stdio::null())
            .stdout(Stdio::from(log.try_clone().unwrap()))
            .stderr(Stdio::from(log))
            .kill_on_drop(true)
            .spawn()
            .unwrap();

        let provider = Arc::new(rustls::crypto::aws_lc_rs::default_provider());
        let versions: &[&rustls::SupportedProtocolVersion] = if tls12 {
            &[&rustls::version::TLS12]
        } else {
            &[&rustls::version::TLS13]
        };
        let mut server_tls = rustls::ServerConfig::builder_with_provider(Arc::clone(&provider))
            .with_protocol_versions(versions)
            .unwrap()
            .with_no_client_auth()
            .with_single_cert(
                vec![cert.der().clone()],
                PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(signing_key.serialize_der())),
            )
            .unwrap();
        server_tls.alpn_protocols = vec![b"http/1.1".to_vec()];
        let mut roots = rustls::RootCertStore::empty();
        roots.add(cert.der().clone()).unwrap();
        let mut client_tls = rustls::ClientConfig::builder_with_provider(provider)
            .with_safe_default_protocol_versions()
            .unwrap()
            .with_root_certificates(roots)
            .with_no_client_auth();
        client_tls.alpn_protocols = vec![b"http/1.1".to_vec()];
        let mut peer = Self {
            child,
            directory,
            address,
            certificate,
            acceptor: TlsAcceptor::from(Arc::new(server_tls)),
            connector: TlsConnector::from(Arc::new(client_tls)),
        };
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            if let Some(status) = peer.child.try_wait().unwrap() {
                panic!("sing-box exited during startup: {status}");
            }
            if TcpStream::connect(peer.address).await.is_ok() {
                return peer;
            }
            assert!(Instant::now() < deadline, "sing-box readiness timed out");
            sleep(Duration::from_millis(20)).await;
        }
    }
}

impl Drop for Peer {
    fn drop(&mut self) {
        let _ = self.child.start_kill();
        if std::thread::panicking() {
            eprintln!(
                "sing-box fixture log:\n{}",
                std::fs::read_to_string(self.directory.0.join("server.log")).unwrap_or_default()
            );
        }
    }
}

struct PrefixedStream {
    prefix: std::io::Cursor<Vec<u8>>,
    stream: TcpStream,
}

impl AsyncRead for PrefixedStream {
    fn poll_read(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> Poll<std::io::Result<()>> {
        if self.prefix.position() < self.prefix.get_ref().len() as u64 {
            return Pin::new(&mut self.prefix).poll_read(cx, buf);
        }
        Pin::new(&mut self.stream).poll_read(cx, buf)
    }
}

impl AsyncWrite for PrefixedStream {
    fn poll_write(
        mut self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        Pin::new(&mut self.stream).poll_write(cx, buf)
    }
    fn poll_flush(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Pin::new(&mut self.stream).poll_flush(cx)
    }
    fn poll_shutdown(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Pin::new(&mut self.stream).poll_shutdown(cx)
    }
}

struct Observer {
    address: SocketAddr,
    hellos: mpsc::UnboundedReceiver<Vec<u8>>,
    task: JoinHandle<()>,
}

impl Observer {
    async fn start(peer: &Peer, tls12: bool) -> Self {
        let listener = TcpListener::bind(SocketAddr::new(peer.address.ip(), 0))
            .await
            .unwrap();
        let address = listener.local_addr().unwrap();
        let destination = peer.address;
        let acceptor = peer.acceptor.clone();
        let connector = peer.connector.clone();
        let (send, hellos) = mpsc::unbounded_channel();
        let task = tokio::spawn(async move {
            let mut tasks = tokio::task::JoinSet::new();
            loop {
                tokio::select! {
                    accepted = listener.accept() => {
                        let (mut stream, _) = accepted.unwrap();
                        let acceptor = acceptor.clone();
                        let connector = connector.clone();
                        let send = send.clone();
                        tasks.spawn(async move {
                            let mut record = [0; 5];
                            stream.read_exact(&mut record).await.unwrap();
                            assert_eq!(record[0], 22);
                            let length = usize::from(u16::from_be_bytes([record[3], record[4]]));
                            assert!(length <= 16 * 1024);
                            let mut hello = record.to_vec();
                            hello.resize(5 + length, 0);
                            stream.read_exact(&mut hello[5..]).await.unwrap();
                            let input = PrefixedStream { prefix: std::io::Cursor::new(hello.clone()), stream };
                            let mut inbound = acceptor.accept(input).await.unwrap();
                            assert_eq!(inbound.get_ref().1.alpn_protocol(), Some(b"http/1.1".as_slice()));
                            assert_eq!(inbound.get_ref().1.protocol_version(), Some(if tls12 { rustls::ProtocolVersion::TLSv1_2 } else { rustls::ProtocolVersion::TLSv1_3 }));
                            let upstream = TcpStream::connect(destination).await.unwrap();
                            let mut upstream = connector.connect(ServerName::try_from(SERVER_NAME).unwrap(), upstream).await.unwrap();
                            let mut request = Vec::new();
                            while !request.ends_with(b"\r\n\r\n") {
                                request.push(inbound.read_u8().await.unwrap());
                                assert!(request.len() < 16 * 1024);
                            }
                            let request_text = std::str::from_utf8(&request).unwrap();
                            assert!(request_text.starts_with(&format!("GET {REQUEST_PATH} HTTP/1.1\r\n")));
                            let headers = request_text.to_ascii_lowercase();
                            assert!(headers.contains(&format!("host: {HOST}\r\n")));
                            assert!(headers.contains(&format!("{HEADER}: {HEADER_VALUE}\r\n")));
                            send.send(hello).unwrap();
                            upstream.write_all(&request).await.unwrap();
                            let _ = tokio::io::copy_bidirectional(&mut inbound, &mut upstream).await;
                        });
                    }
                    result = tasks.join_next(), if !tasks.is_empty() => {
                        if let Some(Err(error)) = result { panic!("observer task failed: {error}"); }
                    }
                }
            }
        });
        Self {
            address,
            hellos,
            task,
        }
    }
}

impl Drop for Observer {
    fn drop(&mut self) {
        self.task.abort();
    }
}

fn adapter(
    peer: &Peer,
    address: SocketAddr,
    profile: Profile,
    alpn: Vec<String>,
) -> Arc<dyn TransitAdapter> {
    let config = client_config(&peer.certificate, address, profile.name(), alpn);
    build(&config).unwrap()
}

fn client_config(
    certificate: &str,
    address: SocketAddr,
    fingerprint: &str,
    alpn: Vec<String>,
) -> TransitProxyConfig {
    TransitProxyConfig {
        id: TransitProxyId::new("ordinary-tls-fingerprint"),
        source: None,
        protocol: "vless".to_owned(),
        endpoint: PolicyEndpoint {
            host: address.ip().to_string(),
            port: address.port(),
        },
        credentials_ref: None,
        labels: Default::default(),
        tags: Default::default(),
        weight: 100,
        options: TransitOptions {
            tls: Some(TransitTls {
                enabled: true,
                server_name: Some(SERVER_NAME.to_owned()),
                truststore: Vec::new(),
                certificate: vec![certificate.to_owned()],
                alpn,
                fingerprint: Some(fingerprint.to_owned()),
                ..Default::default()
            }),
            transport: Some(TransitTransport {
                kind: "ws".to_owned(),
                path: Some(REQUEST_PATH.to_owned()),
                host: vec![HOST.to_owned()],
                headers: BTreeMap::from([(HEADER.to_owned(), HEADER_VALUE.to_owned())]),
                ..Default::default()
            }),
            udp: Some(true),
            ..Default::default()
        },
    }
}

fn build(
    config: &TransitProxyConfig,
) -> Result<Arc<dyn TransitAdapter>, pathchord_transit::TransitError> {
    let credential = TransitCredential::new(BTreeMap::from([("uuid".to_owned(), UUID.to_owned())]));
    AdapterRegistry::for_configs(
        Arc::new(NoTransitCredentials),
        Duration::from_secs(5),
        [config],
    )
    .unwrap()
    .build_with_credential(config, &credential)
}

fn destination(address: SocketAddr) -> ConnectRequest {
    ConnectRequest {
        destination: Endpoint {
            host: address.ip().to_string(),
            port: address.port(),
        },
    }
}

#[derive(Debug, PartialEq, Eq)]
struct NormalizedHello {
    ciphers: Vec<u16>,
    extensions: Vec<(u16, Vec<u8>)>,
    alpn: Vec<u8>,
}

fn normalize_hello(wire: &[u8], profile: Profile) -> NormalizedHello {
    fn take<'a>(bytes: &'a [u8], offset: &mut usize, length: usize) -> &'a [u8] {
        let result = &bytes[*offset..*offset + length];
        *offset += length;
        result
    }
    fn number(bytes: &[u8], offset: &mut usize) -> u16 {
        u16::from_be_bytes(take(bytes, offset, 2).try_into().unwrap())
    }
    fn normalize(value: u16) -> u16 {
        if value.to_be_bytes()[0] == value.to_be_bytes()[1] && value & 0x0f0f == 0x0a0a {
            0x0a0a
        } else {
            value
        }
    }
    fn numbers(bytes: &[u8]) -> Vec<u8> {
        assert!(bytes.len().is_multiple_of(2));
        bytes
            .as_chunks::<2>()
            .0
            .iter()
            .flat_map(|bytes| normalize(u16::from_be_bytes(*bytes)).to_be_bytes())
            .collect()
    }
    let hello = if wire[0] == 22 { &wire[5..] } else { wire };
    assert_eq!(hello[0], 1);
    let length = usize::from(hello[1]) << 16 | usize::from(hello[2]) << 8 | usize::from(hello[3]);
    assert_eq!(hello.len(), length + 4);
    assert_eq!(&hello[4..6], &[3, 3]);
    let mut offset = 4 + 2 + 32;
    let session_length = usize::from(take(hello, &mut offset, 1)[0]);
    assert_eq!(session_length, 32);
    take(hello, &mut offset, session_length);
    let cipher_length = usize::from(number(hello, &mut offset));
    let ciphers = numbers(take(hello, &mut offset, cipher_length))
        .as_chunks::<2>()
        .0
        .iter()
        .map(|value| u16::from_be_bytes(*value))
        .collect();
    let compression_length = usize::from(take(hello, &mut offset, 1)[0]);
    assert_eq!(take(hello, &mut offset, compression_length), &[0]);
    let extension_length = usize::from(number(hello, &mut offset));
    let block = take(hello, &mut offset, extension_length);
    assert_eq!(offset, hello.len());
    let mut extensions = Vec::new();
    let mut alpn = None;
    let mut cursor = 0;
    while cursor < block.len() {
        let kind = normalize(number(block, &mut cursor));
        let length = usize::from(number(block, &mut cursor));
        let body = take(block, &mut cursor, length);
        let value = match kind {
            0x000a | 0x000d => {
                let size = usize::from(u16::from_be_bytes(body[..2].try_into().unwrap()));
                assert_eq!(size, body.len() - 2);
                numbers(&body[2..])
            }
            0x0010 => {
                alpn = Some(body.to_vec());
                Vec::new()
            }
            0x0015 => {
                assert!(body.iter().all(|byte| *byte == 0));
                Vec::new()
            }
            0x002b => {
                assert_eq!(usize::from(body[0]), body.len() - 1);
                numbers(&body[1..])
            }
            0x0033 => {
                let mut cursor = 0;
                assert_eq!(usize::from(number(body, &mut cursor)), body.len() - 2);
                let mut result = Vec::new();
                while cursor < body.len() {
                    let group = normalize(number(body, &mut cursor));
                    let size = number(body, &mut cursor);
                    let key = take(body, &mut cursor, usize::from(size));
                    if group == 0x0a0a {
                        assert_eq!(key, &[0]);
                    }
                    result.extend_from_slice(&group.to_be_bytes());
                    result.extend_from_slice(&size.to_be_bytes());
                }
                result
            }
            0xfe0d => {
                assert_eq!(&body[..4], &[0, 0, 1, 0]);
                if matches!(profile, Profile::Firefox) {
                    assert!([1, 3].contains(&body[4]));
                } else {
                    assert_eq!(body[4], 1);
                }
                assert_eq!(&body[6..8], &[0, 32]);
                let payload_length =
                    usize::from(u16::from_be_bytes(body[40..42].try_into().unwrap()));
                if matches!(profile, Profile::Firefox) {
                    assert_eq!(payload_length, 239);
                } else {
                    assert!([144, 176, 208, 240].contains(&payload_length));
                }
                assert_eq!(body.len(), 42 + payload_length);
                vec![0, 0, 1, 0, 1, 0, 32]
            }
            _ => body.to_vec(),
        };
        extensions.push((kind, value));
    }
    if matches!(profile, Profile::Chrome) {
        assert_eq!(extensions.first().unwrap().0, 0x0a0a);
        assert_eq!(extensions.last().unwrap().0, 0x0a0a);
        extensions.sort();
    }
    NormalizedHello {
        ciphers,
        extensions,
        alpn: alpn.expect("missing ALPN"),
    }
}

fn assert_matches_dae_profile(hello: &[u8], profile: Profile) {
    let mut actual = normalize_hello(hello, profile);
    let mut reference = normalize_hello(profile.reference(), profile);
    assert_eq!(actual.alpn, b"\0\x09\x08http/1.1");
    actual.alpn.clear();
    reference.alpn.clear();
    assert_eq!(
        actual, reference,
        "{profile:?} ClientHello differs from dae/uTLS 1.8.2"
    );
}

async fn exercise(profile: Profile, ip: IpAddr, tls12: bool, explicit_alpn: bool) {
    let peer = Peer::start(ip, tls12).await;
    let mut observer = Observer::start(&peer, tls12).await;
    let alpn = if explicit_alpn {
        vec!["http/1.1".to_owned()]
    } else {
        Vec::new()
    };
    let client = adapter(&peer, observer.address, profile, alpn.clone());
    let target = TcpListener::bind(SocketAddr::new(ip, 0)).await.unwrap();
    let address = target.local_addr().unwrap();
    let upload: Vec<u8> = (0..393_333).map(|index| (index % 251) as u8).collect();
    let download: Vec<u8> = (0..412_777).map(|index| (index % 239) as u8).collect();
    let upstream = async {
        let (mut connection, _) = target.accept().await.unwrap();
        let (mut read, mut write) = connection.split();
        let (received, sent) = tokio::join!(
            async {
                let mut data = vec![0; upload.len()];
                read.read_exact(&mut data).await.unwrap();
                data
            },
            write.write_all(&download)
        );
        sent.unwrap();
        assert_eq!(received, upload);
    };
    let downstream = async {
        let stream = client.connect(destination(address)).await.unwrap();
        let (mut read, mut write) = tokio::io::split(stream);
        let (sent, received) = tokio::join!(
            async {
                write.write_all(&upload).await.unwrap();
                write.flush().await.unwrap();
            },
            async {
                let mut data = vec![0; download.len()];
                read.read_exact(&mut data).await.unwrap();
                data
            }
        );
        let () = sent;
        assert_eq!(received, download);
    };
    timeout(Duration::from_secs(15), async {
        tokio::join!(upstream, downstream)
    })
    .await
    .unwrap_or_else(|_| panic!("{profile:?} {ip} TLS12={tls12} TCP timed out"));
    let hello = timeout(Duration::from_secs(1), observer.hellos.recv())
        .await
        .unwrap()
        .unwrap();
    assert_matches_dae_profile(&hello, profile);

    let target = UdpSocket::bind(SocketAddr::new(ip, 0)).await.unwrap();
    let address = target.local_addr().unwrap();
    let client = adapter(&peer, observer.address, profile, alpn);
    let upstream = async {
        let mut bytes = [0; 2048];
        for _ in 0..2 {
            let (length, peer) = target.recv_from(&mut bytes).await.unwrap();
            target.send_to(&bytes[..length], peer).await.unwrap();
        }
    };
    let downstream = async {
        let mut socket = client.connect_udp(destination(address)).await.unwrap();
        for payload in [b"fingerprint-udp".as_slice(), &[0x6d; 1400]] {
            socket.send(payload).await.unwrap();
            assert_eq!(socket.receive().await.unwrap(), payload);
        }
        socket.close().await.unwrap();
    };
    timeout(Duration::from_secs(15), async {
        tokio::join!(upstream, downstream)
    })
    .await
    .unwrap_or_else(|_| panic!("{profile:?} {ip} TLS12={tls12} UDP timed out"));
    let hello = timeout(Duration::from_secs(1), observer.hellos.recv())
        .await
        .unwrap()
        .unwrap();
    assert_matches_dae_profile(&hello, profile);
}

#[tokio::test]
#[ignore = "requires PATHCHORD_TEST_SING_BOX pointing to sing-box 1.14.4"]
async fn ordinary_fingerprints_match_dae_and_relay_vless_websocket_over_tls13() {
    for profile in [
        Profile::Chrome,
        Profile::Ios,
        Profile::Edge,
        Profile::Qq,
        Profile::Firefox,
    ] {
        for ip in [
            IpAddr::V4(Ipv4Addr::LOCALHOST),
            IpAddr::V6(Ipv6Addr::LOCALHOST),
        ] {
            for explicit_alpn in [false, true] {
                exercise(profile, ip, false, explicit_alpn).await;
            }
        }
    }
}

#[tokio::test]
#[ignore = "requires PATHCHORD_TEST_SING_BOX pointing to sing-box 1.14.4"]
async fn ordinary_fingerprints_match_dae_and_relay_vless_websocket_over_tls12() {
    for profile in [
        Profile::Chrome,
        Profile::Ios,
        Profile::Edge,
        Profile::Qq,
        Profile::Firefox,
    ] {
        for ip in [
            IpAddr::V4(Ipv4Addr::LOCALHOST),
            IpAddr::V6(Ipv6Addr::LOCALHOST),
        ] {
            for explicit_alpn in [false, true] {
                exercise(profile, ip, true, explicit_alpn).await;
            }
        }
    }
}

#[test]
fn unknown_tls_fingerprint_is_rejected_before_dialing() {
    let certificate = rcgen::generate_simple_self_signed(vec![SERVER_NAME.to_owned()])
        .unwrap()
        .cert
        .pem();
    let config = client_config(
        &certificate,
        "127.0.0.1:443".parse().unwrap(),
        "unrecognized-browser",
        Vec::new(),
    );
    assert!(matches!(
        build(&config),
        Err(pathchord_transit::TransitError::Unsupported(_))
    ));
}

