#[tokio::test]
#[ignore = "requires PATHCHORD_TEST_SING_BOX pointing to sing-box 1.14.4"]
async fn ordinary_fingerprints_still_verify_the_ca_and_server_name() {
    let peer = Peer::start(IpAddr::V4(Ipv4Addr::LOCALHOST), false).await;
    let other_certificate = rcgen::generate_simple_self_signed(vec![SERVER_NAME.to_owned()])
        .unwrap()
        .cert
        .pem();
    for profile in [
        Profile::Chrome,
        Profile::Ios,
        Profile::Edge,
        Profile::Qq,
        Profile::Firefox,
    ] {
        let mut wrong_name =
            client_config(&peer.certificate, peer.address, profile.name(), Vec::new());
        wrong_name.options.tls.as_mut().unwrap().server_name =
            Some("wrong.pathchord.test".to_owned());
        let mut wrong_ca =
            client_config(&other_certificate, peer.address, profile.name(), Vec::new());
        assert!(wrong_ca.options.tls.as_ref().unwrap().certificate[0] != peer.certificate);
        wrong_ca.options.tls.as_mut().unwrap().insecure = false;
        for config in [wrong_name, wrong_ca] {
            let client = build(&config).unwrap();
            assert!(
                timeout(
                    Duration::from_secs(5),
                    client.connect(destination(peer.address))
                )
                .await
                .expect("TLS verification did not complete")
                .is_err()
            );
        }
    }
}
